#include <vector>
#include <algorithm>
using namespace std;

class Solution {
public:
    int stoneGameVI(vector<int>& aliceValues, vector<int>& bobValues) {
        int n = aliceValues.size();
        vector<pair<int, int>> stones(n);
        for (int i = 0; i < n; ++i) {
            stones[i] = {aliceValues[i], bobValues[i]};
        }
        sort(stones.begin(), stones.end(), [](const pair<int, int>& a, const pair<int, int>& b) {
            return (a.first + a.second) > (b.first + b.second);
        });
        int alice = 0, bob = 0;
        for (int i = 0; i < n; ++i) {
            if (i % 2 == 0) alice += stones[i].first;
            else bob += stones[i].second;
        }
        if (alice > bob) return 1;
        if (alice < bob) return -1;
        return 0;
    }
};

import java.util.*;

class Solution {
    public int stoneGameVI(int[] aliceValues, int[] bobValues) {
        int n = aliceValues.length;
        Integer[] idx = new Integer[n];
        for (int i = 0; i < n; ++i) idx[i] = i;
        Arrays.sort(idx, (a, b) -> Integer.compare(aliceValues[b] + bobValues[b], aliceValues[a] + bobValues[a]));
        int alice = 0, bob = 0;
        for (int i = 0; i < n; ++i) {
            if (i % 2 == 0) alice += aliceValues[idx[i]];
            else bob += bobValues[idx[i]];
        }
        if (alice > bob) return 1;
        if (alice < bob) return -1;
        return 0;
    }
}

